#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    /* Argument count checks */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    if (argc > 0x41) {               /* 65 arguments max */
        puts("TOO_MANY");
        return 0;
    }

    /* Length check for every argument (including program name) */
    for (int i = 0; i < argc; ++i) {
        if (strlen(argv[i]) > 0x400) {   /* 1024 characters max */
            puts("TOO_LONG");
            return 0;
        }
    }

    /* Compute longest common prefix of argv[1] … argv[argc‑1] */
    const char *first = argv[1];
    size_t prefix_len = strlen(first);

    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && first[j] == s[j]) {
            ++j;
        }
        prefix_len = j;               /* shrink prefix to the common part */
        if (prefix_len == 0) {
            break;                    /* no common prefix any more */
        }
    }

    /* Output the prefix character‑by‑character, then a newline */
    for (size_t i = 0; i < prefix_len; ++i) {
        putc(first[i], stdout);
    }
    putc('\n', stdout);

    return 0;
}
